OPTIONAL MATCH path = (source)-[:send_to*]->(target)
RETURN source.tag AS source_tag, target.tag AS target_tag, path IS NOT NULL AS can_reach }

MATCH (source:PlantItem {tag: "E-7-4"})
RETURN source.tag AS source_tag,
       "V-41-4" AS target_tag,
       EXISTS {
         MATCH (source)-[:send_to*1..]->(:PlantItem {tag: "V-41-4"})
       } AS reachable Be safe query allows internal node regardless PlantItem target yes.

